-- evt:disc
RegisterEvent(13, nil, function(continueStep)
    if continueStep == 2 then
        evt.SetDoorState(3, DoorAction.Open)
        evt.SetDoorState(4, DoorAction.Open)
        evt.SetDoorState(9, DoorAction.Open)
        evt.SetDoorState(5, DoorAction.Open)
        evt.SetDoorState(6, DoorAction.Open)
        evt.PlaySoundName("xeen_sphinx_stir", 832, -4160, 1300)
        evt.CameraShake(1, 2)
        XeenQuests.hook("q-c9.name_right")
        return
    end
    if continueStep ~= nil then
        evt.PlaySoundName("xeen_sphinx_stir", 832, -4160, 1300)
        evt.DamagePlayer(Players.All, const.Damage.Physical, 30)
        SetValue(MapVar(3), 1)
        return
    end
    if not ((not (IsQBitSet(QBit(112181)))) and (IsAtLeast(MapVar(3), 0) and not IsAtLeast(MapVar(3), 1))) then
        if IsQBitSet(QBit(112181)) then XeenQuests.hook("q-c9.name_right") end
        return
    end
    evt.AskQuestion(13, 1, 0, 2, "What is my name?", {"golux"})
end, nil)

